test('vatSummary calculates base and vat correctly for single line', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const line = issued.value.lines[0];
  const expectedBase = lineTotal(line) - lineDiscount(line);
  const expectedVat = lineVAT(line);
  const r = vatSummary([issued.value]);
  assert.equal(r.ok, true);
  assert.equal(r.value[0].base, expectedBase);
  assert.equal(r.value[0].vat, expectedVat);
});

test('vatSummary sums multiple lines with same VAT rate', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }, { sku: 'STICKER', qty: 5 }],
  });
  const issued = issueInvoice(draft.value, []);
  const line1 = issued.value.lines[0];
  const line2 = issued.value.lines[1];
  const expectedBase = (lineTotal(line1) - lineDiscount(line1)) + (lineTotal(line2) - lineDiscount(line2));
  const expectedVat = lineVAT(line1) + lineVAT(line2);
  const r = vatSummary([issued.value]);
  assert.equal(r.ok, true);
  assert.equal(r.value.length, 1);
  assert.equal(r.value[0].base, expectedBase);
  assert.equal(r.value[0].vat, expectedVat);
});

